class LinearComplexSystem:
    def __init__(self, coefficients: list[list[complex]], constants: list[complex]):
        if not isinstance(coefficients, list) or not isinstance(constants, list):
            raise TypeError("coefficients and constants must be lists")
        n = len(coefficients)
        if len(constants) != n:
            raise ValueError("dimension mismatch")
        numeric = (int, float, complex)
        matrix = []
        for row in coefficients:
            if not isinstance(row, list):
                raise TypeError("each matrix row must be a list")
            if len(row) != n:
                raise ValueError("coefficients must be square")
            if any(isinstance(value, bool) or not isinstance(value, numeric) for value in row):
                raise TypeError("matrix entries must be numeric")
            matrix.append([complex(value) for value in row])
        if any(isinstance(value, bool) or not isinstance(value, numeric) for value in constants):
            raise TypeError("constants must be numeric")
        self._a = matrix
        self._b = [complex(value) for value in constants]

    def solve(self) -> list[complex]:
        n = len(self._b)
        a = [row[:] for row in self._a]
        b = self._b[:]
        for column in range(n):
            pivot = min(range(column, n), key=lambda row: abs(a[row][column]))
            if a[pivot][column] == 0:
                raise ValueError("singular matrix")
            a[column], a[pivot] = a[pivot], a[column]
            b[column], b[pivot] = b[pivot], b[column]
            for row in range(column + 1, n):
                factor = a[row][column] / a[column][column]
                for index in range(column, n):
                    a[row][index] -= factor * a[column][index]
                b[row] -= factor * b[column]
        result = [0j] * n
        for row in range(n - 1, -1, -1):
            result[row] = (b[row] - sum(a[row][j] * result[j] for j in range(row + 1, n))) / a[row][row]
        return result

    def residual(self, solution: list[complex]) -> list[complex]:
        if not isinstance(solution, list):
            raise TypeError("solution must be a list")
        if len(solution) != len(self._b):
            raise ValueError("dimension mismatch")
        numeric = (int, float, complex)
        if any(isinstance(value, bool) or not isinstance(value, numeric) for value in solution):
            raise TypeError("solution entries must be numeric")
        x = [complex(value) for value in solution]
        return [sum(value * x[j] for j, value in enumerate(row)) - self._b[i]
                for i, row in enumerate(self._a)]

